INSERT OR IGNORE INTO memory_aliases SELECT lower(hex(randomblob(16))),id,'preferred editor','preferred editor' FROM memories WHERE memory_key='preferred.editor' AND NOT EXISTS(SELECT 1 FROM memories WHERE lower(memory_key)='preferred editor');
INSERT OR IGNORE INTO memory_aliases SELECT lower(hex(randomblob(16))),id,'default editor','default editor' FROM memories WHERE memory_key='preferred.editor' AND NOT EXISTS(SELECT 1 FROM memories WHERE lower(memory_key)='default editor');
